@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + number : int
  + capacity : int
}

class Person {
  + firstName : string
  + lastName : string
  + birthDate : date
}

class Trainer extends Person {
  + diploma : string
}

class Session {
  + date : date
  + startingHour : time
}

class GroupSession extends Session {
  + type : string
}

class IndividualSession extends Session {}

Center "1" *-- "1..*" Room

Center "1" -- "*" Session
Room "1" -- "*" Session

Person "0..*" -- "*" Session : participates in

Trainer "0..1" -- "*" GroupSession : supervises

@enduml

